-- Generated by medallion from spec/tables/silver_customers.toml. Do not edit by hand.
-- Typed rows with expectations applied; the input to the change flow.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.customers_validated (
  customer_id STRING COMMENT 'Customer identifier',
  email STRING COMMENT 'Customer email address, lower case' MASK ${catalog}.governance.mask_email,
  full_name STRING COMMENT 'Customer full name' MASK ${catalog}.governance.mask_redact,
  country STRING COMMENT 'Country code, upper case',
  segment STRING COMMENT 'Marketing segment, lower case',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  CONSTRAINT customer_id_present EXPECT (customer_id IS NOT NULL AND length(customer_id) > 0) ON VIOLATION DROP ROW,
  CONSTRAINT updated_at_valid EXPECT (updated_at IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT country_is_iso_length EXPECT (country IS NULL OR length(country) = 2),
  CONSTRAINT op_present EXPECT (op IS NOT NULL) ON VIOLATION DROP ROW,
  CONSTRAINT op_known EXPECT (op IS NULL OR op IN ('I', 'U', 'D')) ON VIOLATION FAIL UPDATE
)
COMMENT 'Staging for silver.customers: typed rows that passed validation. Not for consumers.'
TBLPROPERTIES (
  'governance.owner' = 'customer-data',
  'governance.domain' = 'customer',
  'governance.classification' = 'confidential',
  'governance.spec' = 'spec/tables/silver_customers.toml',
  'governance.role' = 'staging'
)
AS SELECT
  try_cast(trim(customer_id) AS STRING) AS customer_id,
  try_cast(lower(trim(email)) AS STRING) AS email,
  try_cast(trim(full_name) AS STRING) AS full_name,
  try_cast(upper(trim(country)) AS STRING) AS country,
  try_cast(lower(trim(segment)) AS STRING) AS segment,
  try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
  try_cast(upper(trim(op)) AS STRING) AS op,
  _source_file,
  _ingested_at
FROM STREAM(${catalog}.bronze.customers);

-- The consumer-facing table. SCD type 2: one row per version of each key.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.customers (
  customer_id STRING COMMENT 'Customer identifier',
  email STRING COMMENT 'Customer email address, lower case' MASK ${catalog}.governance.mask_email,
  full_name STRING COMMENT 'Customer full name' MASK ${catalog}.governance.mask_redact,
  country STRING COMMENT 'Country code, upper case',
  segment STRING COMMENT 'Marketing segment, lower case',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  __START_AT TIMESTAMP COMMENT 'Start of this version (inclusive)',
  __END_AT TIMESTAMP COMMENT 'End of this version (exclusive); null for the current version'
)
COMMENT 'Customer history as a type 2 dimension: one row per version, with the open version marked by a null end. Contains personal data.'
TBLPROPERTIES (
  'governance.owner' = 'customer-data',
  'governance.domain' = 'customer',
  'governance.classification' = 'confidential',
  'governance.spec' = 'spec/tables/silver_customers.toml',
  'governance.role' = 'serving'
);

CREATE FLOW silver_customers_apply_changes AS AUTO CDC INTO ${catalog}.silver.customers
FROM STREAM(${catalog}.silver.customers_validated)
KEYS (customer_id)
APPLY AS DELETE WHEN op = 'D'
SEQUENCE BY updated_at
COLUMNS * EXCEPT (op)
STORED AS SCD TYPE 2
TRACK HISTORY ON * EXCEPT (_ingested_at, _source_file, updated_at);

-- Rows that failed a drop expectation, kept for investigation and replay.
CREATE OR REFRESH STREAMING TABLE ${catalog}.silver.customers_quarantine (
  customer_id STRING COMMENT 'Customer identifier',
  email STRING COMMENT 'Customer email address, lower case' MASK ${catalog}.governance.mask_email,
  full_name STRING COMMENT 'Customer full name' MASK ${catalog}.governance.mask_redact,
  country STRING COMMENT 'Country code, upper case',
  segment STRING COMMENT 'Marketing segment, lower case',
  updated_at TIMESTAMP COMMENT 'Sequence column: when the source row last changed (UTC)',
  op STRING COMMENT 'Change operation, used for deletes only',
  _source_file STRING COMMENT 'Path of the file this row was read from',
  _ingested_at TIMESTAMP COMMENT 'When the pipeline ingested the row',
  failed_rules ARRAY<STRING> COMMENT 'Names of the drop expectations this row failed'
)
COMMENT 'Rows from bronze.customers that failed a drop expectation for silver.customers, with the rules they failed.'
TBLPROPERTIES (
  'governance.owner' = 'customer-data',
  'governance.domain' = 'customer',
  'governance.classification' = 'confidential',
  'governance.spec' = 'spec/tables/silver_customers.toml',
  'governance.role' = 'quarantine'
)
AS SELECT
  *,
  filter(array(
    CASE WHEN coalesce(customer_id IS NOT NULL AND length(customer_id) > 0, false) THEN NULL ELSE 'customer_id_present' END,
    CASE WHEN coalesce(updated_at IS NOT NULL, false) THEN NULL ELSE 'updated_at_valid' END,
    CASE WHEN coalesce(op IS NOT NULL, false) THEN NULL ELSE 'op_present' END
  ), x -> x IS NOT NULL) AS failed_rules
FROM (
  SELECT
    try_cast(trim(customer_id) AS STRING) AS customer_id,
    try_cast(lower(trim(email)) AS STRING) AS email,
    try_cast(trim(full_name) AS STRING) AS full_name,
    try_cast(upper(trim(country)) AS STRING) AS country,
    try_cast(lower(trim(segment)) AS STRING) AS segment,
    try_cast(trim(updated_at) AS TIMESTAMP) AS updated_at,
    try_cast(upper(trim(op)) AS STRING) AS op,
    _source_file,
    _ingested_at
  FROM STREAM(${catalog}.bronze.customers)
)
WHERE NOT coalesce((customer_id IS NOT NULL AND length(customer_id) > 0) AND (updated_at IS NOT NULL) AND (op IS NOT NULL), false);
